 form.onsubmit=async e=>{e.preventDefault();try{const f=new FormData(form),equipment={id:crypto.randomUUID(),name:f.get('name').trim(),grinder:f.get('grinder').trim(),method:f.get('method'),confirmed:f.has('confirmed'),nonpressurized:f.get('method')==='espresso'&&f.get('basketType')==='single-wall',basketType:f.get('method')==='v60'?'filter':f.get('basketType'),architecture:f.has('separateUnits')?'separate':'unknown',minDose:Number(f.get('minDose')),maxDose:Number(f.get('maxDose')),calibration:f.get('calibration'),grinderConfiguration:f.get('grinderConfiguration'),temperatureControl:f.get('temperatureControl'),waterNote:f.get('waterNote'),preparationNote:f.get('preparationNote'),...(f.has('scaleEnabled')?{grindScale:{min:Number(f.get('scaleMin')),max:Number(f.get('scaleMax')),step:Number(f.get('scaleStep')),finer:f.get('scaleFiner'),confirmed:true}}:{}),...(brewerChoice||{}),...(grinderChoice||{})};validateEquipment(equipment);if(equipment.maxDose<5||equipment.minDose>35||equipment.method==='v60'&&(equipment.maxDose<15||equipment.minDose>30))throw Error(t('Confirm a usable dose range on the actual basket or dripper before saving.'));if(equipment.method==='espresso'&&basketMode(equipment)==='unknown')throw Error(t('Choose the installed basket type before saving.'));await save('equipment',equipment);selected.equipment=equipment.id;selected.dose=Math.max(equipment.minDose,Math.min(equipment.maxDose,equipment.method==='v60'?15:18));selected.drink=equipment.method;recipe=null;timerStart=null;elapsed=0;render();toast(t('Your setup is saved. Add a bag of coffee, or start brewing.'));}catch(error){toast(error.message);}};
