function historyPage(){
 $('#main').innerHTML=`<div class="lead"><p class="eyebrow">${t('TASTE, ADJUST, REPEAT')}</p><h1>${t('Small notes.<br>Better mornings.')}</h1></div><section class="panel"><label class="check"><input type="checkbox" id="favorites">${t('Show favorites only')}</label><div id="brews"></div></section>`;
 const show=()=>{$('#brews').innerHTML=data('brew').sort((a,b)=>b.created.localeCompare(a.created)).filter(b=>!$('#favorites').checked||b.decision.status==='keep').map(b=>`<article class="item"><span class="badge">${escape(t(tastes[b.feedback.taste]))}</span><h3>${escape(b.recipe.bean.name)}</h3><p class="muted">${escape(t(drinks[b.recipe.drink]||methods[b.recipe.equipment.method]))} · ${b.feedback.output} g · ${Math.round(b.feedback.seconds)} ${t('sec')} · ${escape(b.created.slice(0,10))}</p><p>${escape(b.decision.message)}</p><button data-brew="${b.id}">${t('Open brew')}</button></article>`).join('')||`<div class="empty"><h2>${t('Your next cup belongs here.')}</h2><p class="muted">${t('After brewing, save the measured dose, output, time and taste.')}</p><a class="button primary" href="#brew">${t('Brew a cup')}</a></div>`;document.querySelectorAll('[data-brew]').forEach(button=>button.onclick=()=>{const b=data('brew').find(x=>x.id===button.dataset.brew);modal(card(b.recipe)+`<p>${t('Measured: {dose} g dose / {output} g output / {seconds} sec',{dose:b.feedback.dose,output:b.feedback.output,seconds:Math.round(b.feedback.seconds)})}</p><h3>${escape(b.decision.message)}</h3><p>${escape(b.feedback.notes)}</p>`);});};show();$('#favorites').onchange=show;
}
async function withBusy(task){if(busy)return;busy=true;document.querySelectorAll('#main button').forEach(b=>b.disabled=true);try{await task();}catch(error){toast(error.message);}finally{busy=false;render();}}
function downloadJSON(value,name){
 const blob=new Blob([JSON.stringify(value,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');
 a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
}
function dataPage(){
 $('#main').innerHTML=`<div class="lead"><p class="eyebrow">${t('YOUR COFFEE, YOUR RECORDS')}</p><h1>${t('On this device. Yours.')}</h1><p class="muted">${t('{setups} setups · {batches} batches · {brews} brews',{setups:data('equipment').length,batches:data('bean').length,brews:data('brew').length})}</p></div><div class="grid"><section class="panel"><h2>${t('No account. No AI. No API key.')}</h2><p>${t('Recipes and suggestions are calculated here using fixed, versioned rules. No sign-up, subscriptions, tracking SDKs or automatic uploads.')}</p><p class="hint">${t('This is not cloud storage. Moving this HTML file, changing browser or opening another device does not transfer your records. Export a backup first.')}</p><div class="actions"><button class="primary" id="export">${t('Export backup')}</button><button id="import">${t('Import backup')}</button></div><input id="file" type="file" accept="application/json,.json" hidden><p class="muted">${t('Backups include your private notes and history. Share them only with people you trust. Import merges compatible records without duplicates or silent overwrites.')}</p><button id="persist">${t('Request persistent storage')}</button><p class="muted">${t('Your browser can decline this request. Browser cleanup, private browsing and device loss can still remove data; keep a separate backup.')}</p><button class="danger" id="clear-local">${t('Clear this local library')}</button></section><div><section class="panel"><h2>${t('Language')}</h2><p class="muted">${t('Daycup is available in English and Chinese. Model names, specifications and source notes stay in their original language. Saved recipes keep the language they were written in.')}</p><div class="actions">${Object.entries(languages).map(([code,name])=>`<button type="button" data-language="${code}" class="${code===currentLanguage()?'primary':''}">${name}</button>`).join('')}</div></section><section class="panel"><h2>${t('Two ways to keep Daycup')}</h2><p><strong>${t('On the web:')}</strong> ${t('open Daycup at its SideCourt address. On a phone, use Add to Home Screen to keep it as an app icon; on a desktop browser, use Install app. After the first visit it works offline.')}</p><p><strong>${t('As a file:')}</strong> ${t('keep the standalone Daycup.html file and open it in a desktop browser. Everything it needs is included. If your browser blocks file storage, use the included loopback launcher instead.')}</p><p class="muted">${t('Records stay in the browser where you saved them. Each address, browser and device has its own library; move records with Export and Import.')}</p><p class="muted">Daycup ${escape(appVersion)} · ${escape(knowledgeVersion)} · ${t('Espresso, Americano, iced Americano and V60. Actual basket capacity and grinder calibration still need your confirmation. A software test is not a taste test.')}</p><p class="muted"><a href="privacy.html">${t('Privacy & data')}</a></p></section><section class="panel"><h2>${t('Previous local libraries')}</h2><p class="muted">${t('An older version may have kept records under an account on this same browser. They remain separate and untouched. No password or server connection is used here.')}</p><button id="legacy">${t('Recover a library on my device')}</button><p class="muted">${t('Use only your own browser profile. Local records are not encrypted or protected from other people using this profile.')}</p></section></div></div>`;
 document.querySelectorAll('[data-language]').forEach(button=>button.onclick=()=>{setLanguage(button.dataset.language);applyChrome();render();});
 $('#export').onclick=()=>downloadJSON({schema:1,entries},'Daycup-backup-'+localToday()+'.json');
 $('#import').onclick=()=>$('#file').click();$('#file').onchange=e=>{const file=e.target.files[0];if(!file)return;withBusy(async()=>{if(file.size>16000000)throw Error(t('The backup exceeds 16 MB.'));const archive=JSON.parse(await file.text());if(archive.schema!==1)throw Error(t('This backup version is not supported.'));await merge(archive.entries,scope());entries=await list(scope());toast(t('Backup imported. Matching records were not duplicated.'));});};
 $('#persist').onclick=async()=>{try{const granted=await navigator.storage?.persist?.();toast(t(granted?'Persistent storage granted. Still keep a backup.':'Persistent storage was not granted by this browser. Export a backup regularly.'));}catch{toast(t('This browser cannot grant persistent storage here. Export a backup.'));}};
 $('#clear-local').onclick=()=>{modal(`<h2>${t('Clear this local library?')}</h2><p>${t('Export a backup first. There is no automatic cloud copy. Only the current local library will be removed; old separate libraries remain.')}</p><button class="danger" id="confirm-clear">${t('Permanently clear this library')}</button>`);$('#confirm-clear').onclick=()=>withBusy(async()=>{await clearScope(scope());entries=[];recipe=null;timerStart=null;$('#dialog').close();toast(t('The current local library has been cleared.'));});};
 $('#legacy').onclick=async()=>{try{
  const rows=await new Promise((resolve,reject)=>{const r=db.transaction('entries').objectStore('entries').getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});
  const groups=[...new Set(rows.map(x=>x.scope))].filter(x=>x!==scope());
  modal(`<h2>${t('Recover only your own records')}</h2><p>${t('Local libraries are not a login security boundary. Select a library you own. Exporting does not merge or delete it. Import that backup separately to copy it into the current library.')}</p>${groups.map((g,i)=>`<p><button data-legacy="${i}">${t('Export previous library {number} · {count} records',{number:i+1,count:rows.filter(x=>x.scope===g).length})}</button></p>`).join('')||'<p>'+t('No previous account libraries were found on this browser and address.')+'</p>'}`);
  document.querySelectorAll('[data-legacy]').forEach(button=>button.onclick=()=>{const g=groups[Number(button.dataset.legacy)];if(confirm(t('I own this local library and want to export its private records.')))downloadJSON({schema:1,entries:rows.filter(x=>x.scope===g).map(({scope,...entry})=>entry)},'Daycup-previous-library-'+localToday()+'.json');});
 }catch(error){toast(error.message);}};
}
window.addEventListener('hashchange',()=>{render();$('#main').focus();});
window.addEventListener('offline',()=>connection('Offline · Saved on this device'));
window.addEventListener('online',()=>connection('On this device · No automatic uploads'));
try {
 applyChrome();
 db=await openDB();entries=await list(scope());
 const bundled=globalThis.DAYCUP_BUNDLE;
 const load=async name=>{const r=await fetch('./'+name);if(!r.ok)throw Error(t('Cannot load {name}',{name}));return r.json();};
 const results=await Promise.allSettled([bundled?Promise.resolve(bundled.equipment):load('equipment-directory.json'),bundled?Promise.resolve(bundled.beans):load('bean-options.json')]);
 if(results[0].status==='fulfilled'){equipmentDirectory=curatedDirectory(results[0].value);initializeKnowledge(equipmentDirectory);}
 if(results[1].status==='fulfilled')beanOptions=results[1].value;
 render();connection(bundled?'Offline file · No account':'Saved on this device · No account');
 if(!equipmentDirectory||!beanOptions)toast(t('Some directory choices could not load. You can still enter your own equipment and beans.'));
 if(!bundled&&'serviceWorker' in navigator&&['http:','https:'].includes(location.protocol)){
  navigator.serviceWorker.register('./sw.js',{scope:'./',updateViaCache:'none'}).then(()=>navigator.serviceWorker.ready).then(()=>connection('Ready offline · Records on this device')).catch(()=>toast(t('Offline caching could not be installed. Keep this page open and export your records.')));
 }
}catch(error){$('#main').innerHTML=`<h1>${t('We could not open your local records.')}</h1><p>${t('Check that your browser allows sites to save data. Your existing records have not been reset. For a downloaded file, try the included loopback launcher.')}</p>`;toast(error.message);}
